using Moq;
using TurnKeyOps.Lib.Dtos;
using TurnKeyOps.Lib.Utils;
using TurnKeyOps.Services;
namespace TurnKeyOps.Authorization.Tests;
public sealed class ConstructionPaymentTests
{
 private sealed class Lease:IAsyncDisposable{public ValueTask DisposeAsync()=>ValueTask.CompletedTask;}
 private sealed class Fixture
 {
  public Guid Tenant=Guid.NewGuid(),Customer=Guid.NewGuid(),Job=Guid.NewGuid(),Item=Guid.NewGuid();public FinanceState State=FinanceTests.State();public Mock<IConstructionPaymentProvider> Provider=new();public ConstructionPaymentService Service;public int Saves;
  public Fixture()
  {
   State.Version="v1";State.CashAccounts.Add(new("bank","Bank","1000","","","USD"));State.Construction.Contracts.Add(new(Job,Customer,1000,0,[new("one","Work",1000)]));var journal=FinanceLedger.Post(State,new(2026,9,1),"construction-invoice","opening-app","Issued construction billing",[new("1100",1000,0,Job,CustomerId:Customer),new("3000",0,1000)],"owner").Id;State.OpenItems.Add(new(Item,"AR",Customer,"APP-1",new(2026,9,1),new(2026,9,30),1000,journal,Job));State.Construction.Applications.Add(new(Guid.NewGuid(),Job,"1",new(2026,9,1),new(2026,9,30),[new("one",1000)],"INVOICED",JournalId:journal,InvoiceId:Item));
   var store=new Mock<IFinanceStore>();store.Setup(s=>s.ReadAsync(Tenant,It.IsAny<CancellationToken>())).ReturnsAsync(()=>JobConfigurationService.Clone(State));store.Setup(s=>s.SaveAsync(Tenant,It.IsAny<FinanceState>(),It.IsAny<string>(),It.IsAny<CancellationToken>())).Callback<Guid,FinanceState,string,CancellationToken>((_,value,version,_)=>{Assert.Equal(State.Version,version);FinanceIntegrity.ValidateTransition(State,value);value.Version="v"+(++Saves+1);State=JobConfigurationService.Clone(value);}).Returns(Task.CompletedTask);
   var authority=new Mock<IFinanceAuthority>();authority.Setup(a=>a.CanControlAsync(It.IsAny<CancellationToken>())).ReturnsAsync(true);var user=new Mock<IUserContext>();user.SetupGet(u=>u.TenantId).Returns(Tenant);user.SetupGet(u=>u.UserId).Returns(Guid.NewGuid());var fence=new Mock<IFinanceSourceCoordinator>();fence.Setup(c=>c.AcquireAsync(Tenant,It.IsAny<CancellationToken>())).ReturnsAsync(new Lease());Provider.Setup(p=>p.Configured(Tenant)).Returns(true);Provider.Setup(p=>p.MerchantAccount(Tenant)).Returns("acct_tenant");Provider.Setup(p=>p.CreateAsync(Tenant,It.IsAny<ConstructionPaymentIntent>(),It.IsAny<CancellationToken>())).ReturnsAsync(new ConstructionCheckout("cs_one","https://checkout.stripe.com/c/pay/test"));Service=new(store.Object,fence.Object,authority.Object,user.Object,Provider.Object);
  }
  public Task<object> Create(Guid? id=null)=>Service.CommandAsync(new(){Id=id??Guid.NewGuid(),OpenItemId=Item,ExpectedVersion=State.Version,CashAccountId="bank",Reason="Owner approved checkout"});
  public Task<object> Receive(string eventId="evt_one",string account="acct_tenant",decimal amount=1000){var intent=State.ConstructionPayments.Single();Provider.Setup(p=>p.VerifyAsync(eventId,It.IsAny<IReadOnlyDictionary<string,string>>(),It.IsAny<CancellationToken>())).ReturnsAsync(new ConstructionVerifiedPayment(Tenant,intent.Id,Item,Customer,eventId,"cs_one",amount,"USD",new(2026,9,15),account));return Service.ReceiveAsync(eventId,new Dictionary<string,string>());}
 }
 [Fact]public async Task DurableIntentReusesProviderIdentityAfterAmbiguousFailure()
 {var f=new Fixture();var id=Guid.NewGuid();f.Provider.SetupSequence(p=>p.CreateAsync(f.Tenant,It.IsAny<ConstructionPaymentIntent>(),It.IsAny<CancellationToken>())).ThrowsAsync(new IOException("Unconfirmed")).ReturnsAsync(new ConstructionCheckout("cs_one","https://checkout.stripe.com/c/pay/test"));await Assert.ThrowsAsync<IOException>(()=>f.Create(id));Assert.Single(f.State.ConstructionPayments);Assert.Equal("PENDING",f.State.ConstructionPayments[0].Status);await f.Service.CommandAsync(new(){Action="retry",TargetId=id,ExpectedVersion=f.State.Version,Reason="Retry original identity"});Assert.Equal("READY",f.State.ConstructionPayments[0].Status);Assert.Equal(id,f.State.ConstructionPayments[0].Id);Assert.Empty(f.State.Settlements);}
 [Fact]public async Task PaidCheckoutPostsCashAndArOnceWithoutRecognizingRevenue()
 {var f=new Fixture();await f.Create();await f.Receive();await f.Receive("evt_duplicate");Assert.Single(f.State.Settlements);Assert.Single(f.State.ConstructionPaymentReceipts);Assert.Equal("PAID",f.State.ConstructionPayments.Single().Status);var journal=f.State.Journals.Single(j=>j.SourceType=="construction-payment");Assert.Equal(0,journal.Lines.Sum(l=>l.Debit-l.Credit));Assert.DoesNotContain(journal.Lines,l=>l.Account==f.State.Policy.Accounts["revenue"]);}
 [Fact]public async Task MerchantAndAmountMismatchFailWithoutAnyReceiptOrPosting()
 {var f=new Fixture();await f.Create();await Assert.ThrowsAsync<ArgumentException>(()=>f.Receive(account:"acct_other"));await Assert.ThrowsAsync<ArgumentException>(()=>f.Receive(amount:1));Assert.Empty(f.State.Settlements);Assert.Empty(f.State.ConstructionPaymentReceipts);}
 [Fact]public async Task ClosedPeriodRetainsVerifiedReceiptPendingForControlledReconciliation()
 {var f=new Fixture();await f.Create();f.State.Periods.ForEach(p=>p.Status="CLOSED");await f.Receive();Assert.Single(f.State.ConstructionPaymentReceipts);Assert.Equal("PENDING",f.State.ConstructionPaymentReceipts.Single().Status);Assert.Empty(f.State.Settlements);Assert.Equal("RECEIVED",f.State.ConstructionPayments.Single().Status);}
 [Fact]public async Task CancellationExpiresOriginalSessionBeforeAllowingReplacement()
 {var f=new Fixture();await f.Create();var id=f.State.ConstructionPayments.Single().Id;await f.Service.CommandAsync(new(){Action="cancel",TargetId=id,ExpectedVersion=f.State.Version,Reason="Owner cancellation"});f.Provider.Verify(p=>p.ExpireAsync(f.Tenant,It.Is<ConstructionPaymentIntent>(i=>i.Id==id),"cs_one",It.IsAny<CancellationToken>()),Times.Once);Assert.Equal("CANCELLED",f.State.ConstructionPayments.Single().Status);}
 [Fact]public async Task StalePendingCheckoutCannotDispatchChangedArBalance()
 {var f=new Fixture();f.Provider.Setup(p=>p.CreateAsync(f.Tenant,It.IsAny<ConstructionPaymentIntent>(),It.IsAny<CancellationToken>())).ThrowsAsync(new IOException("Unconfirmed"));await Assert.ThrowsAsync<IOException>(()=>f.Create());var intent=f.State.ConstructionPayments.Single();var journal=FinanceLedger.Post(f.State,new(2026,9,10),"manual-payment","prior","Receipt",[new("1000",100,0),new("1100",0,100)],"owner");f.State.Settlements.Add(new(Guid.NewGuid(),"payment",f.Customer,new(2026,9,10),100,"bank","manual","prior","prior",journal.Id,[new(f.Item,100)]));await Assert.ThrowsAsync<ArgumentException>(()=>f.Service.CommandAsync(new(){Action="retry",TargetId=intent.Id,ExpectedVersion=f.State.Version,Reason="Retry original"}));f.Provider.Verify(p=>p.CreateAsync(f.Tenant,It.IsAny<ConstructionPaymentIntent>(),It.IsAny<CancellationToken>()),Times.Once);}
 [Fact]public async Task FutureDatedArCannotBeDispatched(){var f=new Fixture();f.State.OpenItems[0]=f.State.OpenItems[0] with{Date=DateOnly.FromDateTime(DateTime.UtcNow).AddDays(1)};await Assert.ThrowsAsync<ArgumentException>(()=>f.Create());Assert.Empty(f.State.ConstructionPayments);}
 [Fact]public async Task ReceiptPredatingArRemainsPending(){var f=new Fixture();await f.Create();f.State.OpenItems[0]=f.State.OpenItems[0] with{Date=new(2026,9,20)};await f.Receive();Assert.Equal("PENDING",f.State.ConstructionPaymentReceipts.Single().Status);Assert.Empty(f.State.Settlements);}
 [Fact]public async Task UnconfiguredTenantCannotCreateIntent()
 {var f=new Fixture();f.Provider.Setup(p=>p.Configured(f.Tenant)).Returns(false);await Assert.ThrowsAsync<ArgumentException>(()=>f.Create());Assert.Empty(f.State.ConstructionPayments);}
}
